changeSet.sql:
CREATE TABLE public.product (
    id           BIGINT       NOT NULL,
    created_date TIMESTAMP(6),
    updated_date TIMESTAMP(6),
    name         VARCHAR(255) NOT NULL,
    description  VARCHAR(255) NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_product_name UNIQUE (name)
);

CREATE SEQUENCE public.product_id_generator START WITH 1 INCREMENT BY 1;

CREATE SEQUENCE public.stop_factor_id_generator START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE public.stop_factor_condition_id_generator START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE public.stop_factor_check_id_generator START WITH 1 INCREMENT BY 1;

rollback.sql:
DROP SEQUENCE public.stop_factor_check_id_generator;
DROP SEQUENCE public.stop_factor_condition_id_generator;
DROP SEQUENCE public.stop_factor_id_generator;
